#!/bin/bash
#SBATCH -J {JOB_NAME}
#SBATCH -A p0023647
#SBATCH -t {TIME}
#SBATCH --mem-per-cpu={MEMORY_VALUE}
#SBATCH -n {PROCESSOR_NUMBER}
#SBATCH -N 1
#SBATCH -e /work/scratch/as12vapa/{PROJECT_NAME}/{FOLDER_NAME}/%x.err.%j
#SBATCH -o /work/scratch/as12vapa/{PROJECT_NAME}/{FOLDER_NAME}/%x.out.%j
#SBATCH --mail-type=End
#SBATCH -C i01

# ------------------------------------------------------------------
# KLAIM 2025 revision 2 -- 2D job, generated by 02_create_jobs.sh
# ------------------------------------------------------------------
working_folder_name="{FOLDER_NAME}"
working_directory="$HPC_SCRATCH/{PROJECT_NAME}/$working_folder_name"
container="$HOME/dolfinx_alex/alex-dolfinx.sif"
bindpath="$HOME/dolfinx_alex/shared:/home,$working_directory:/work"

# case parameters
WSTEG={WSTEG}
MATERIAL="{MATERIAL}"
GC_MICRO_PARAM={GC_MICRO_PARAM}
SIG_Y={SIG_Y}
HARD={HARD}
EMBEDDING="{EMBEDDING}"
NROWS={NROWS}
CRACK_FACTOR={CRACK_FACTOR}
GEOMETRY="{GEOMETRY}"

# global parameters (same for all cases of the study)
NHOLES={NHOLES}
DHOLE={DHOLE}
E0={E0}
E1={E1}
MESH_FILE="{MESH_FILE}"
LAM_MICRO_PARAM={LAM_MICRO_PARAM}
MUE_MICRO_PARAM={MUE_MICRO_PARAM}
EPS_PARAM={EPS_PARAM}
ELEMENT_ORDER={ELEMENT_ORDER}
BETA={BETA}
ETA={ETA}
MOB={MOB}
SIG_Y_EMBEDDING={SIG_Y_EMBEDDING}
BC_MODULI="{BC_MODULI}"
E_BC={E_BC}
NU_BC={NU_BC}
STOP_FRACTION={STOP_FRACTION}
POSTPROCESSING_INTERVAL={POSTPROCESSING_INTERVAL}
EVENT_SNAPSHOTS={EVENT_SNAPSHOTS}

LCRACK=$(awk "BEGIN {print $CRACK_FACTOR * ($WSTEG + $DHOLE)}")

echo "[$(date)] job $SLURM_JOB_ID case $working_folder_name: wsteg=$WSTEG material=$MATERIAL gc=$GC_MICRO_PARAM sig_y=$SIG_Y hard=$HARD embedding=$EMBEDDING nrows=$NROWS lcrack=$LCRACK geometry=$GEOMETRY"
cd $HPC_SCRATCH

set -e
srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/mesh_effective_stiffness.py \
    --dhole "$DHOLE" --wsteg "$WSTEG" --e0 "$E0" --geometry "$GEOMETRY"

srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/run_effective_stiffness.py \
    --lam_micro_param "$LAM_MICRO_PARAM" --mue_micro_param "$MUE_MICRO_PARAM"

srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/mesh_fracture_adaptive.py \
    --nholes "$NHOLES" --dhole "$DHOLE" --wsteg "$WSTEG" --e0 "$E0" --e1 "$E1" --nrows "$NROWS" --geometry "$GEOMETRY"

srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/get_mesh_info.py --mesh_file "$MESH_FILE"
set +e

srun -n {PROCESSOR_NUMBER} apptainer exec --bind $bindpath $container python3 $working_directory/run_simulation.py \
    --mesh_file "$MESH_FILE" \
    --in_crack_length "$LCRACK" \
    --lam_micro_param "$LAM_MICRO_PARAM" \
    --mue_micro_param "$MUE_MICRO_PARAM" \
    --gc_micro_param "$GC_MICRO_PARAM" \
    --eps_param "$EPS_PARAM" \
    --element_order "$ELEMENT_ORDER" \
    --material "$MATERIAL" \
    --sig_y "$SIG_Y" \
    --hard "$HARD" \
    --sig_y_embedding "$SIG_Y_EMBEDDING" \
    --beta "$BETA" \
    --eta "$ETA" \
    --mob "$MOB" \
    --embedding "$EMBEDDING" \
    --bc_moduli "$BC_MODULI" \
    --E_bc "$E_BC" \
    --nu_bc "$NU_BC" \
    --stop_fraction "$STOP_FRACTION" \
    --postprocessing_interval "$POSTPROCESSING_INTERVAL" \
    --event_snapshots "$EVENT_SNAPSHOTS"

EXITCODE=$?
echo "[$(date)] finished with exit code $EXITCODE"
exit $EXITCODE
